-- commitment transaction functions

create or replace function private.upsert_finance_commitment(p_commitment_id text,p_name text,p_category text,p_total numeric,p_due_date date default null,p_note text default '') returns private.finance_commitments language plpgsql security definer set search_path='' as $$ declare v private.finance_commitments; begin if not private.has_panorama_finanzas_access() then raise exception 'Acceso no autorizado' using errcode='42501'; end if; if trim(coalesce(p_name,''))='' or p_total<=0 then raise exception 'Compromiso inválido'; end if; insert into private.finance_commitments(id,name,category,total,due_date,note) values(p_commitment_id,trim(p_name),coalesce(nullif(trim(p_category),''),'otro_compromiso'),p_total,p_due_date,coalesce(p_note,'')) on conflict(id) do update set name=excluded.name,category=excluded.category,total=excluded.total,due_date=excluded.due_date,note=excluded.note,updated_at=now() returning * into v; if v.paid_amount>v.total then raise exception 'El total no puede ser menor que lo ya pagado'; end if; return v; end $$;
create or replace function public.upsert_finance_commitment(p_commitment_id text,p_name text,p_category text,p_total numeric,p_due_date date default null,p_note text default '') returns private.finance_commitments language sql security invoker set search_path='' as $$ select * from private.upsert_finance_commitment($1,$2,$3,$4,$5,$6); $$;
create or replace function private.post_commitment_payment(p_payment_id text,p_occurred_on date,p_commitment_id text,p_amount numeric,p_account_id text,p_note text default '') returns private.finance_commitment_payments language plpgsql security definer set search_path='' as $$ declare v private.finance_commitment_payments;c private.finance_commitments;a private.finance_accounts;l private.finance_ledger_entries;begin if not private.has_panorama_finanzas_access() then raise exception 'Acceso no autorizado' using errcode='42501';end if;if p_amount<=0 then raise exception 'Pago inválido';end if;if exists(select 1 from private.finance_commitment_payments where id=p_payment_id) then select * into v from private.finance_commitment_payments where id=p_payment_id;return v;end if;select * into c from private.finance_commitments where id=p_commitment_id for update;if not found or not c.active then raise exception 'Compromiso no encontrado o inactivo';end if;if c.total-c.paid_amount<p_amount then raise exception 'El pago supera el saldo pendiente del compromiso';end if;select * into a from private.finance_accounts where id=p_account_id for update;if not found or not a.active or a.current_balance<p_amount then raise exception 'Saldo insuficiente o cuenta inválida';end if;select * into l from private.post_finance_entry(p_payment_id,p_occurred_on,'salida',p_amount,p_account_id,'Pago — '||c.name,coalesce(c.category,'deudas'),'commitment_payment',null,jsonb_build_object('commitmentId',p_commitment_id));update private.finance_commitments set paid_amount=paid_amount+p_amount,updated_at=now() where id=c.id;insert into private.finance_commitment_payments(id,commitment_id,occurred_on,amount,account_id,ledger_entry_id,note) values(p_payment_id,p_commitment_id,p_occurred_on,p_amount,p_account_id,p_payment_id,coalesce(p_note,'')) returning * into v;insert into private.finance_audit_log(actor_user_id,action,entity_type,entity_id,after_data) values(auth.uid(),'create','commitment_payment',p_payment_id,to_jsonb(v));return v;end $$;
create or replace function public.post_commitment_payment(p_payment_id text,p_occurred_on date,p_commitment_id text,p_amount numeric,p_account_id text,p_note text default '') returns private.finance_commitment_payments language sql security invoker set search_path='' as $$ select * from private.post_commitment_payment($1,$2,$3,$4,$5,$6); $$;